    public List<FieldDescriptor> getFieldDescriptors() {
        STTTencentSite site = (STTTencentSite)this.sourceSite;
        return List.of(new FieldDescriptor("url", site.url(), true, false), new FieldDescriptor("secret_id", site.getSecretId(), true, true), new FieldDescriptor("secret_key", site.getSecretKey(), true, true), new FieldDescriptor("eng_ser_vice_type", site.getEngSerViceType(), false, false), new FieldDescriptor("hot_word", site.getHotWord(), true, false));
    }

    @Override
    @Nullable
    public STTSite buildSite(Function<String, String> fieldValues, Consumer<Component> showStatus) {
        String[] split;
        STTTencentSite site = (STTTencentSite)this.sourceSite;
        String url = StringUtils.trimToEmpty((String)fieldValues.apply("url"));
        if (StringUtils.isBlank((CharSequence)url)) {
            showStatus.accept((Component)Translations.URL_IS_EMPTY);
            return null;
        }
        if (StringUtils.isBlank((CharSequence)fieldValues.apply("secret_id"))) {
            showStatus.accept((Component)Translations.SECRET_ID_IS_EMPTY);
            return null;
        }
        if (StringUtils.isBlank((CharSequence)fieldValues.apply("secret_key"))) {
            showStatus.accept((Component)Translations.SECRET_KEY_IS_EMPTY);
            return null;
        }
        StringBuilder hotWordFixed = new StringBuilder();
        for (String line : split = StringUtils.split((String)fieldValues.apply("hot_word"), (char)',')) {
            String[] parts = line.split("\\|");
            if (parts.length != 2) continue;
            String word = parts[0].trim();
            String weightStr = parts[1].trim();
            if (word.isEmpty() || !weightStr.matches("\\d+")) continue;
            hotWordFixed.append(word).append("|").append(weightStr).append(",");
        }
        return new STTTencentSite(site.id(), site.icon(), site.enabled(), url, StringUtils.trimToEmpty((String)fieldValues.apply("secret_id")), StringUtils.trimToEmpty((String)fieldValues.apply("secret_key")), StringUtils.trimToEmpty((String)fieldValues.apply("eng_ser_vice_type")), StringUtils.trimToEmpty((String)hotWordFixed.toString()));
    }
}

